import{_ as i,o as t,c as e,ag as s}from"./chunks/framework.DHSXpJLs.js";const k=JSON.parse('{"title":"AI Skill（aiifc / aiplan / aidxf）","description":"","frontmatter":{},"headers":[],"relativePath":"reference/ai-skill.md","filePath":"reference/ai-skill.md","lastUpdated":1790780265000}'),d={name:"reference/ai-skill.md"};function l(n,a,p,c,o,r){return t(),e("div",null,[...a[0]||(a[0]=[s(`<h1 id="ai-skill-aiifc-aiplan-aidxf" tabindex="-1">AI Skill（aiifc / aiplan / aidxf） <a class="header-anchor" href="#ai-skill-aiifc-aiplan-aidxf" aria-label="Permalink to &quot;AI Skill（aiifc / aiplan / aidxf）&quot;">​</a></h1><p>平台的 AI 生成能力以 skill 包交付。skill 是给 AI agent 的工具包：agent 加载后直接写代码或跑命令来生成模型。它与 <a href="/SourceAEC/reference/ai">AI 接入</a> 的 REST 方式互补——REST 适合改参数这类小修改，skill 适合从零建模型这类大动作。skill 与平台解耦，不部署平台也能单独使用。</p><h2 id="管线总览" tabindex="-1">管线总览 <a class="header-anchor" href="#管线总览" aria-label="Permalink to &quot;管线总览&quot;">​</a></h2><p>plan 到 cad 是管线主干：aiplan 把外部资料整理成任务书，aidxf 把任务书画成图纸，aiifc 再把图纸转成 IFC。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>外部资料 ──► aiplan ──┬─► plan.json（任务书）──────────► aidxf v3 ──► building.json + 各层 DXF ──┬─► bim（ifc）</span></span>
<span class="line"><span>                      └─► bim_supplement.json（BIM 补充）──────────────────────────────────────┘    ▲</span></span>
<span class="line"><span>                                                                                                   │</span></span>
<span class="line"><span>                             ifc 独立管线：design.json（LLM 草稿）──► aiifc ──────────────────────────┘</span></span>
<span class="line"><span>                             cad→ifc 消化管线：building.json + 各 zone DXF ──► aiifc consume-upstream</span></span>
<span class="line"><span>                                 ──► design.json ──► design-build（features.json）──► build-script（IFC）</span></span></code></pre></div><table tabindex="0"><thead><tr><th>skill</th><th>阶段</th><th>输入</th><th>输出</th></tr></thead><tbody><tr><td><code>aiplan</code></td><td>plan，管线入口</td><td>任意外部资料：图片、PPT、文档、对话</td><td><code>plan.json</code> 加 <code>bim_supplement.json</code></td></tr><tr><td><code>aidxfv3</code></td><td>cad，管线中段</td><td><code>plan.json</code> 只读，加用户补充描述</td><td><code>building.json</code> 加各层 DXF</td></tr><tr><td><code>aiifc</code></td><td>bim，管线末段</td><td>消费上游：building、bim_supplement、DXF；或独立：design 草稿</td><td>构建脚本加 IFC</td></tr></tbody></table><h2 id="aiifc-ifc-生成" tabindex="-1">aiifc：IFC 生成 <a class="header-anchor" href="#aiifc-ifc-生成" aria-label="Permalink to &quot;aiifc：IFC 生成&quot;">​</a></h2><p>面向 AI agent 的 IfcOpenShell 建模 skill，让 AI 直接写 <code>ifcopenshell.api</code> 代码。</p><p>skill 结构是 SKILL.md 加参考资产：SKILL.md 是行为宪法；references 里有 103 个 API 分页、8 个组件 recipe 和 13 个可运行 flows；templates 是可复制的完整脚本示例。</p><p>agent 建模的顺序是骨架先行：先 Project 到 Storey 的空间结构，再墙板梁柱等构件，然后开洞和门窗，再补类型材质属性集，最后导出并校验。复杂户型可以先出 design JSON 草稿辅助构思，经规范化后再生成脚本。</p><p>aiifc 提供五个 CLI，都支持 <code>--project-id</code> 把中间产物规范落到项目工作区：</p><table tabindex="0"><thead><tr><th>命令</th><th>输入</th><th>输出</th></tr></thead><tbody><tr><td><code>aiifc consume-upstream</code></td><td>building.json、bim_supplement.json、DXF 目录</td><td>design.json，上游几何到楼层的精确映射</td></tr><tr><td><code>aiifc design-build</code></td><td>design.json</td><td>features.json</td></tr><tr><td><code>aiifc build-script</code></td><td>features.json</td><td>演示 IFC</td></tr><tr><td><code>aiifc design-review</code></td><td>产物 IFC</td><td>质量审查报告</td></tr><tr><td><code>aiifc ifc-inspect</code></td><td>产物 IFC</td><td>结构检查 JSON</td></tr></tbody></table><p>cad 到 ifc 的消化路径：agent 先把上游产物桥接进工作区，跑 consume-upstream 和 design-build，然后在已有脚本上深化，是增量修改不是重写。</p><h2 id="aiplan-plan-阶段" tabindex="-1">aiplan：plan 阶段 <a class="header-anchor" href="#aiplan-plan-阶段" aria-label="Permalink to &quot;aiplan：plan 阶段&quot;">​</a></h2><p>管线入口。把外部资料归一成下游可执行的任务书，全程用提问工具和用户确认设计意图。它不画图、不写 IFC、不做坐标级布局。</p><p>输出两个文件，schema 事实源在包内 <code>references/schemas/</code>：plan.json 给 cad 用，说明要什么在哪盖按什么规范；bim_supplement.json 给 bim 用，补 CAD 覆盖不了的屋顶、特殊结构、属性集。成对产出，过门禁校验后落盘。仅依赖 jsonschema，自包含可迁移。</p><h2 id="aidxf-plan-到-cad" tabindex="-1">aidxf：plan 到 cad <a class="header-anchor" href="#aidxf-plan-到-cad" aria-label="Permalink to &quot;aidxf：plan 到 cad&quot;">​</a></h2><p>CAD 生成正式版框架，后续迭代都在这上面。</p><p>输入是 plan.json，全程只读，加用户的补充描述。输出是 building.json 和逐层 DXF。</p><p>分工原则是 LLM 设计、机器锚定：LLM 只声明哪里有分区、房间多大、和谁相邻，坐标全部交给机器派生，<code>aidxfv3 normalize</code> 是唯一的坐标计算点。流程分五步，每步有断点确认，多楼层裙房塔楼等场景按 zone 并行，支持中断恢复。依赖 ezdxf 和 shapely。</p><h2 id="获取与安装" tabindex="-1">获取与安装 <a class="header-anchor" href="#获取与安装" aria-label="Permalink to &quot;获取与安装&quot;">​</a></h2><p>skill 是 agent 无关的目录包，opencode、Claude Code、Cursor 等都能加载。</p><p>下载：从 GitHub Release 取 <code>&lt;name&gt;-&lt;version&gt;.tar.gz</code>，或在仓库内自助打包：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/skill_pack.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --skill</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> aiifc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --archive</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                 # aiifc</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/skill_pack.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --skill</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> aidxf</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --archive</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                 # aidxf</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/skill_pack.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --skill-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills/aiplan</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --archive</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # aiplan 走 --skill-dir</span></span></code></pre></div><p>产物在 <code>skills/dist/</code>。解压到 agent 的 skill 目录即完成安装，运行时会自动索引 SKILL.md：</p><ul><li>支持 skill 的 agent：安装到该 agent 的用户级或项目级 skill 目录</li><li>Claude Code：<code>~/.claude/skills/&lt;name&gt;/</code></li></ul><p>运行依赖见各包内 requirements.txt：aiifc 要 ifcopenshell、ifcquery、numpy；aidxf 要 ezdxf 和 shapely；aiplan 只要 jsonschema。</p><p>与平台的关系：skill 是 AI 侧入口，编辑服务是服务端运行时，两者配对但可独立使用。只做一次性生成不需要平台；要版本、diff、双角色编辑才需要部署平台。</p><h2 id="与-rest-api-的关系" tabindex="-1">与 REST API 的关系 <a class="header-anchor" href="#与-rest-api-的关系" aria-label="Permalink to &quot;与 REST API 的关系&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式</th><th>场景</th><th>入口</th></tr></thead><tbody><tr><td>REST 编辑 API</td><td>在既有脚本上定向修改，版本与 diff</td><td><code>:8100/models/{id}/...</code>，见 <a href="/SourceAEC/reference/ai">AI 接入</a></td></tr><tr><td>aiifc skill</td><td>从零建模型、大改几何、复现上传 IFC</td><td>agent 直接写 Python</td></tr><tr><td>aiplan 与 aidxf</td><td>plan 到 cad 全链路</td><td>agent 跑 CLI 命令</td></tr></tbody></table><h2 id="版本化发布" tabindex="-1">版本化发布 <a class="header-anchor" href="#版本化发布" aria-label="Permalink to &quot;版本化发布&quot;">​</a></h2><p>每个 skill 独立版本化，版本号写在 SKILL.md frontmatter，与平台版本解耦。发布四步：改版本号并在包内 CHANGELOG 追加条目；用打包器产出 tar.gz；跑 <code>python -m pytest tests/skill/ -q</code> 校验；打 tag 并建 GitHub Release。</p><h2 id="许可" tabindex="-1">许可 <a class="header-anchor" href="#许可" aria-label="Permalink to &quot;许可&quot;">​</a></h2><p>aiifc 是 Apache-2.0，文档参考自 IfcOpenShell 官方文档；aiplan 和 aidxf 是 MIT。</p>`,34)])])}const f=i(d,[["render",l]]);export{k as __pageData,f as default};
